"""Printed 215–217: general circle form and three-point construction."""
from math import sqrt
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_reviewed_line_concurrency import product
from math12_reviewed_conics_intro import ellipse
from math12_native_geometry import geometry,path
def circle_points(center_line=False):
 paths=[path(ellipse(245,160,100,100))]
 labels=[(321,246,'A(x₁,y₁)'),(319,75,'B(x₂,y₂)')] if center_line else [(322,246,'A(x₁,y₁)'),(95,140,'B(x₂,y₂)')]
 if center_line:
  paths.append(path([(110,280),(380,40)],dash=True));labels.extend([(191,150,'(−g,−f)'),(250,180,'ax+by+c₁=0')])
 else:labels.append((227,43,'C(x₃,y₃)'))
 return geometry('Figure 8.4' if center_line else 'Figure 8.3','Circle through two points with center on a given line' if center_line else 'Circle through three non-collinear points',paths,labels,points=[{'x':315.710678,'y':230.710678},{'x':315.710678 if center_line else 147.020408,'y':89.289322 if center_line else 140},{'x':245,'y':160 if center_line else 60}],size=(450,300))
PAGES=[page('112_page_1.jpg',215,[paragraph('The standard form of a circle with radius r and center (h,k) is:'),eq(r'(x-h)^2+(h-k)^2=r^2','ii'),note('The printed second square uses h−k. The preceding distance proof and the following example establish the intended (y−k)². The source expression is retained here and the correct equation is used in the learning solution.'),paragraph('If the center of the circle is at the origin (h,k) = (0,0), then the circle equation (ii) becomes:'),eq(r'x^2+y^2=r^2','iii'),
 heading('Example 1'),paragraph('Determine the equation of a circle with center at (−2,1) and radius r = 3.'),heading('Solution'),paragraph('The standard form of the equation of a circle is (x−h)²+(y−k)² = r², where (h,k) are the coordinates of the centre and r is the radius. In this equation h = −2, k = 1 and r = 3; substitute these values into the standard equation.'),eq(r'(x-(-2))^2+(y-1)^2=3^2'),eq(r'(x+2)^2+(y-1)^2=9'),
 heading('8.2.2 General form of an equation of a circle'),paragraph('The arrangement of the general equation of the second degree in x and y that may represent a circle through the following procedure: The general equation of the second degree in variables x and y is:'),eq(r'ax^2+2hxy+by^2+2gx+2fy+c=0','i'),paragraph('Divide out both sides of equation (i) by a to obtain:'),eq(r'x^2+\frac{2h}axy+\frac bay^2+\frac{2g}ax+\frac{2f}ay+\frac ca=0','ii'),eq(r'x^2+\frac{2h}axy+\frac bay^2+2g_1x+2f_1y+c_1=0,\quad g_1=\frac ga,f_1=\frac fa,c_1=\frac ca'),
 paragraph('The rearranged equation (ii) of the general equation of the second degree (i) in x and y gives the general equation of a circle if and only if b/a = 1 and 2h/a = 0:'),eq(r'x^2+y^2+2g_1x+2f_1y+c_1=0'),eq(r'x^2+y^2+2gx+2fy+c=0','iii'),paragraph('g₁ = g, f₁ = f, c₁ = c. Adding and subtracting g² and f² in equation (iii):'),eq(r'x^2+2gx+g^2-g^2+y^2+2fy+f^2-f^2+c=0'),eq(r'(x+g)^2+(y+f)^2=g^2+f^2-c'),eq(r'[x-(-g)]^2+[y-(-f)]^2=(\sqrt{g^2+f^2-c})^2'),
 paragraph('The locus of a point (x,y) which moves in such a way that its distance from a fixed point (−g,−f) is constant and equals √(g²+f²−c). This of course represents a circle.'),heading('For general equation of circle x²+y²+2gx+2fy+c = 0'),paragraph('Center and Radius: The coordinates of the center are (−g,−f) and the radius is r = √((−g)²+(−f)²−c).'),paragraph('Independent Constant: The general equation contains three independent constants g, f and c. They can be determined from the three independent conditions.'),heading('Nature of the Circle'),paragraph('If g²+f²−c > 0, then, the circle is real and different from zero.'),note('Division by a requires a ≠ 0. The conditions b = a and h = 0 identify the circle-shaped quadratic part in fixed Cartesian axes; a real nondegenerate circle additionally requires a positive squared radius. Relabelling g₁,f₁,c₁ as g,f,c is a change of coefficient notation, not equality of the original and divided coefficients. Three constraints must be independent and consistent to determine a unique circle.')]),
 page('112_page_2.jpg',216,[paragraph('If g²+f²−c = 0, then, the circle shrinks into a point (−g,−f). It is called point circle.'),paragraph('If g²+f²−c < 0, then, the circle is imaginary or virtual.'),paragraph('The coefficients of x² is equal to the coefficients of y², and there is no term containing xy and the square of the radius r² ≥ 0.'),note('For real x,y the sum (x+g)²+(y+f)² cannot be negative. The source’s imaginary/virtual case therefore has no real points. A point circle is degenerate; a genuine circle has r² > 0.'),
 heading('Example 2'),paragraph('Find the center and radius of a circle 45x²+45y²−60y+36x+19 = 0.'),heading('Solution'),paragraph('The given circle equation is rearranged to obtain:'),eq(r'x^2+y^2-\frac43x+\frac45y+\frac{19}{45}=0','i'),paragraph('Dividing by 45. The circle equation (i) is compared to the general form of an equation of circle to obtain the values of g,f and c:'),eq(r'2g=-\frac43\ \Rightarrow\ g=-\frac23,\quad 2f=\frac45\ \Rightarrow\ f=\frac25,\quad c=\frac{19}{45}'),paragraph('The center and radius of the given circle are therefore:'),eq(r'(-g,-f)=\left(\frac23,-\frac25\right),\quad r=\sqrt{\frac49+\frac4{25}-\frac{19}{45}}=\sqrt{\frac{41}{225}}=\frac{\sqrt{41}}{15}'),
 note('The question has −60y+36x, but its rearrangement attaches −4/3 to x and +4/5 to y. Correct division gives +4x/5−4y/3, hence the center is (−2/5,2/3). The radius √41/15 happens to be unchanged because the squared center coordinates are merely exchanged. The displayed source working is kept distinct from the corrected solution.'),
 heading('8.2.3 The equation of a circle passing through'),paragraph('A. three non-collinear points; B. two points and having its centre on a given line; C. two points and equation of tangent at one of these points is known; D. two points and touching a given line.'),heading('A. Equation passing through three non-collinear points'),paragraph('Consider the general equation a circle is given by x²+y²+2gx+2fy+c = 0. If the given circle is passing through the three non-collinear points, say, A(x₁,y₁), B(x₂,y₂) and C(x₃,y₃), then these points must satisfy the general equation of a circle. Now put the above three points in the given equation of a circle, i.e.:'),circle_points(),eq(r'x_1^2+y_1^2+2gx_1+2fy_1+c=0','i'),eq(r'x_2^2+y_2^2+2gx_2+2fy_2+c=0','ii'),eq(r'x_3^2+y_3^2+2gx_3+2fy_3+c=0','iii'),
 heading('Example 3'),paragraph('Find the equation of a circle which passes through the three points A(1,0), B(0,−6) and C(3,4).'),heading('Solution'),paragraph('The required equation of a circle is x²+y²+2gx+2fy+c = 0 (i) which passes through the three points A(1,0), B(0,−6) and C(3,4), which gives a system of three linear equations in the three unknowns g,f and c:'),eq(r'1+2g+c=0\ \Rightarrow\ 2g+c=-1'),eq(r'36-12f+c=0\ \Rightarrow\ -12f+c=-36'),eq(r'25+6g+8f+c=0\ \Rightarrow\ 6g+8f+c=-25','ii')]),
 page('113_page_1.jpg',217,[paragraph('The system of three linear equation (ii) in matrix form:'),product([[[2,0,1],[0,-12,1],[6,8,1]],[['g'],['f'],['c']],[[-1],[-36],[-25]]],['','='],suffix='Ax = b'),paragraph('whose augmented matrix is:'),product([[[2,0,1,-1],[0,-12,1,-36],[6,8,1,-25]]],prefix='A|b ='),paragraph('Reduce the augmented matrix in an echelon form to obtain:'),product([[[2,0,1,-1],[0,-12,1,-36],[0,8,-2,-22]]],prefix='R',suffix='−3R₁ = R₃+(−3)R₁'),product([[[2,0,1,-1],[0,-12,1,-36],[0,0,'−4/3',-46]]],prefix='R',suffix='(2/3)R₂ = R₃+(2/3)R₂'),eq(r'2g+c=-1,\quad -12f+c=-36,\quad(-\frac43)c=-46','iii'),
 paragraph('Third equation of the system (iii) is giving c = 69/2 which is used in second and first equations to obtain the values of f = 47/8 and g = −71/4.'),paragraph('The values of g = −71/4, f = 47/8 and c = 69/2 are used in equation (iii) to obtain the required circle equation:'),eq(r'x^2+y^2+2\left(-\frac{71}4\right)x+2\left(\frac{47}8\right)y+\frac{69}2=0'),eq(r'x^2+y^2-\frac{71}2x+\frac{47}4y+\frac{69}2=0'),eq(r'4x^2+4y^2-142x+47y+138=0'),note('The row operations correctly reduce the third row by adding multiples of other rows. The source’s leading labels “−3R₁ =” and “(2/3)R₂ =” are incomplete operation notation: the intended updates are R₃ ← R₃−3R₁ and then R₃ ← R₃+(2/3)R₂. The circle equation cited as (iii) here is the general form, rather than the newly numbered triangular system.'),
 heading('B. Equation of circle passing through two points and having its centre on a given line'),paragraph('Consider the general equation of a circle is given by x²+y²+2gx+2fy+c = 0. If the given circle is passing through two points, say, A(x₁,y₁) and B(x₂,y₂), then these points must satisfy the general equation of a circle. Now put these two points in the given equation of a circle, i.e.:'),eq(r'x_1^2+y_1^2+2gx_1+2fy_1+c=0','i'),eq(r'x_2^2+y_2^2+2gx_2+2fy_2+c=0','ii'),circle_points(True),paragraph('Also, the given straight line ax+by+c₁ = 0 passes through the center (−g,−f) of the circle.')])]
for p in PAGES:
 p.update(title='CONICS-I',visualStatus='Complete general-circle derivation and Examples 1–3 with native matrices and point-construction figures',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':112 if p['page']<=216 else 113,'side':'right' if p['page']==216 else 'left','reason':'Original coefficient order, mistaken rearrangement and all matrix entries visually checked'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
 ('1','Determine the equation of a circle with center (−2,1) and radius 3.',['Use the distance definition: (x−h)²+(y−k)² = r².','Identify h = −2, k = 1 and r = 3.','Then x−h = x+2 and y−k = y−1.','Square the radius: r² = 9.','Thus (x+2)²+(y−1)² = 9.','Expansion gives x²+y²+4x−2y−4 = 0, whose completed squares recover the stated center and radius.'],'(x+2)²+(y−1)² = 9.',215,215),
 ('2','Find the center and radius of 45x²+45y²−60y+36x+19 = 0.',['Divide every coefficient by 45: x²+y²+(4/5)x−(4/3)y+19/45 = 0.','Compare with x²+y²+2gx+2fy+c = 0, giving g = 2/5, f = −2/3 and c = 19/45.','The center is (−g,−f) = (−2/5,2/3).','Compute r² = g²+f²−c = 4/25+4/9−19/45.','With denominator 225 this is (36+100−95)/225 = 41/225 > 0.','Thus r = √41/15 and the standard form is (x+2/5)²+(y−2/3)² = 41/225.','Expand this form and multiply by 45 to recover 45x²+45y²+36x−60y+19 = 0 exactly. The source’s rearranged coefficients are swapped, giving its incorrect center.'],'Center (−2/5,2/3); radius √41/15.',216,216),
 ('3','Find the circle through A(1,0), B(0,−6), C(3,4).',['Write x²+y²+2gx+2fy+c = 0. The displacements AB = (−1,−6) and AC = (2,4) have cross product 8 ≠ 0, so the three points are non-collinear.','Substitution gives 2g+c = −1, −12f+c = −36, and 6g+8f+c = −25.','Subtract three times the first equation from the third: 8f−2c = −22.','Add (2/3) of the second equation to this result: (−4/3)c = −46, hence c = 69/2.','Then −12f = −36−69/2 = −141/2, so f = 47/8. Also 2g = −1−69/2 = −71/2, so g = −71/4.','The circle is x²+y²−(71/2)x+(47/4)y+69/2 = 0, or 4x²+4y²−142x+47y+138 = 0.','Check A: 4−142+138 = 0. Check B: 144−282+138 = 0. Check C: 36+64−426+188+138 = 0.','Its center is (71/4,−47/8) and squared radius is 20165/64 > 0, confirming a real circle through all three points.'],'4x²+4y²−142x+47y+138 = 0.',216,217)]:
 EXAMPLES.append({'num':n,'title':'Circle Equation','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':start,'pageEnd':end,'jpg':'112_page_1.jpg' if start==215 else '112_page_2.jpg','verification':'Complete source example and continuation visually checked'}]})
